package com.aistock.prediction.verification;
import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.http.HttpStatus;
public final class VerificationDueRepository {
 private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final Clock clock;private final int hour;
 public VerificationDueRepository(JdbcTemplate jdbc,ObjectMapper mapper,Clock clock,int hour){this.jdbc=jdbc;this.mapper=mapper;this.clock=clock;this.hour=hour;}
 public Page due(LocalDate through,UUID after,int limit){var local=clock.instant().atZone(ZoneId.of("Asia/Shanghai"));var cutoff=local.toLocalDate().minusDays(local.getHour()<hour?1:0);if(through==null||through.isBefore(LocalDate.of(1990,1,1))||through.isAfter(cutoff)||limit<1||limit>50)throw VerificationRepository.error("VERIFICATION_REQUEST_INVALID",HttpStatus.BAD_REQUEST);
  var rows=jdbc.query("select f.prediction_id,f.instrument_id,f.snapshot_json from forecast_request f left join forecast_verification_head h on h.prediction_id=f.prediction_id left join forecast_verification_version v on v.version_id=h.current_version_id and v.prediction_id=f.prediction_id and v.rule_version=? where f.state='SUCCEEDED' and f.prediction_id>? and JSON_UNQUOTE(JSON_EXTRACT(f.snapshot_json,'$.prediction.points[0].targetDate'))<=? and (v.version_id is null or CAST(JSON_UNQUOTE(JSON_EXTRACT(v.evaluation_json,'$.verifiedCount')) AS UNSIGNED)<5) order by f.prediction_id limit ?",(rs,n)->{try{var snapshot=mapper.readTree(rs.getString("snapshot_json"));var end=LocalDate.parse(snapshot.path("input").path("originDate").asText()).plusDays(90);return new Item(UUID.fromString(rs.getString("prediction_id")),rs.getString("instrument_id"),through.isAfter(end)?end:through,VerificationRecords.RULE);}catch(Exception e){throw VerificationRepository.error("VERIFICATION_RECORD_INVALID",HttpStatus.INTERNAL_SERVER_ERROR);}},VerificationRecords.RULE,after==null?"":after.toString(),through.toString(),limit+1);
  boolean more=rows.size()>limit;var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Page(through,items,more?items.get(items.size()-1).predictionId():null);
 }
 public Page affected(String instrument,LocalDate through,UUID after,int limit){var local=clock.instant().atZone(ZoneId.of("Asia/Shanghai"));var cutoff=local.toLocalDate().minusDays(local.getHour()<hour?1:0);if(instrument==null||!instrument.matches("(SH|SZ)[0-9]{6}")||through==null||through.isBefore(LocalDate.of(1990,1,1))||through.isAfter(cutoff)||limit<1||limit>50)throw VerificationRepository.error("VERIFICATION_REQUEST_INVALID",HttpStatus.BAD_REQUEST);
  var rows=jdbc.query("select prediction_id,instrument_id,snapshot_json from forecast_request where state='SUCCEEDED' and instrument_id=? and prediction_id>? and JSON_UNQUOTE(JSON_EXTRACT(snapshot_json,'$.prediction.points[0].targetDate'))<=? order by prediction_id limit ?",(rs,n)->{try{var snapshot=mapper.readTree(rs.getString("snapshot_json"));var end=LocalDate.parse(snapshot.path("input").path("originDate").asText()).plusDays(90);return new Item(UUID.fromString(rs.getString("prediction_id")),rs.getString("instrument_id"),through.isAfter(end)?end:through,VerificationRecords.RULE);}catch(Exception e){throw VerificationRepository.error("VERIFICATION_RECORD_INVALID",HttpStatus.INTERNAL_SERVER_ERROR);}},instrument,after==null?"":after.toString(),through.toString(),limit+1);
  boolean more=rows.size()>limit;var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Page(through,items,more?items.get(items.size()-1).predictionId():null);
 }
 public record Item(UUID predictionId,String instrumentId,LocalDate dueThrough,String ruleVersion){}
 public record Page(LocalDate cutoffDate,List<Item> items,UUID nextCursor){}
}
